protocol P_r
    recv i64

protocol P_s
    send i64

fn w1(a1: session P_r)
    let v0 = <- a1

fn w2(a0: session P_r, b1: session P_s)
    b1 <- 1
    let v0 = <- a0

fn main()
    let (a0, b0) = chan[session P_r](1)
    let (a1, b1) = chan[session P_r](1)
    b0 <- 1
    spawn w1(a1)
    spawn w2(a0, b1)
    emit 0

